test.query:
t=iws_part_$(date +%s%N)
${CLICKHOUSE_CLIENT} --allow_insert_into_iceberg 1 --max_insert_threads 4 --iceberg_insert_max_rows_in_data_file 1000000 --query "
    DROP TABLE IF EXISTS iws_part_run SYNC;
    CREATE TABLE iws_part_run AS iws_part ENGINE = IcebergS3(perf_s3, filename = '${t}/') PARTITION BY toMonthNumSinceEpoch(l_shipdate);
    INSERT INTO iws_part_run SELECT * FROM tpch10.lineitem;
    SELECT throwIf(sum(record_count) != (SELECT count() FROM tpch10.lineitem) OR uniqExact(partition) != 84 OR count() > 4 * 84) FROM system.iceberg_files WHERE database = 'default' AND table = 'iws_part_run';
    DROP TABLE iws_part_run SYNC"

t=iws_files_$(date +%s%N)
${CLICKHOUSE_CLIENT} --allow_insert_into_iceberg 1 --max_insert_threads 4 --max_block_size 10000 --min_insert_block_size_rows 10000 --min_insert_block_size_bytes 0 --iceberg_insert_max_rows_in_data_file 10000 --query "
    DROP TABLE IF EXISTS iws_files_run SYNC;
    CREATE TABLE iws_files_run AS iws_part ENGINE = IcebergS3(perf_s3, filename = '${t}/');
    INSERT INTO iws_files_run SELECT * FROM tpch10.lineitem WHERE l_orderkey % 10 = 0;
    SELECT throwIf(sum(record_count) != (SELECT count() FROM tpch10.lineitem WHERE l_orderkey % 10 = 0) OR max(record_count) >= 20000 OR countIf(record_count < 10000) > 4) FROM system.iceberg_files WHERE database = 'default' AND table = 'iws_files_run';
    DROP TABLE iws_files_run SYNC"
